const $=s=>document.querySelector(s),id=new URLSearchParams(location.search).get('id'),key=new URLSearchParams(location.hash.slice(1)).get('key');let order=null,cat=null,privateLink=location.href;const headers=()=>({'Content-Type':'application/json',...(key?{Authorization:'Bearer '+key}:{})});
const labels={saved:'Saved, no payment',awaiting_payment:'Awaiting payment',checkout_pending:'Payment setup needs our review',awaiting_review:'Paid, awaiting our review',generating:'Preparing an illustration',building:'Preparing your book',proof_ready:'Your proof is ready to check',awaiting_approval:'Your proof approved, awaiting our final review',approved:'Approved, awaiting release to print',submitting:'Sending to printer',supplier_unknown:'Printer confirmation under review',submitted:'Sent to printer',on_hold:'On hold, our team will help'};
async function call(action,data){const r=await fetch('/api/orders/'+id+(action?'/'+action:''),{method:data?'POST':'GET',headers:headers(),...(data?{body:JSON.stringify({revision:order?.revision,...data})}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not read this book.');return d;}
async function refresh(){try{const r=await fetch('/api/orders/catalog');cat=await r.json();order=await call('');if(order.paymentProvider==='ziina'&&order.status==='awaiting_payment')order=await call('check-payment',{});$('#title').textContent=order.story.title;$('#content').hidden=false;$('#message').textContent='';$('#status').textContent=labels[order.status]||'Our team is checking your book';$('#format').textContent=order.label;$('#amount').textContent='£'+(order.amount/100).toFixed(2);$('#address').textContent=[order.recipient.name,...Object.values(order.recipient.address)].filter(Boolean).join(', ');$('#dedication').textContent=order.dedication||'For '+order.names;$('#pay').hidden=!(cat.checkoutEnabled&&order.paymentStatus==='unpaid'&&['saved','awaiting_payment'].includes(order.status));$('#payment-note').textContent=order.paymentStatus==='paid'?(order.paymentMode==='test'?'TEST payment only. No real payment or printing.':'Payment confirmed. Nothing prints until both approvals are complete.'):'No payment has been recorded.'+(cat.checkoutEnabled?' Continue to secure payment when ready.':' Checkout is not open yet. Your book is saved with no charge or commitment.');privateLink=(await call('return-link',{})).url;$('#private-link').textContent=privateLink;$('#private-link').href=privateLink;$('#story').replaceChildren();const reader=document.createElement('div');reader.className='story-reader';reader.tabIndex=0;reader.setAttribute('aria-label','Swipe or use arrow keys to turn story pages');for(const [i,p] of order.story.spreads.entries()){const article=document.createElement('article'),folio=document.createElement('small'),text=document.createElement('p');folio.textContent='Story page '+(i+1)+' of '+order.story.spreads.length;text.textContent=p.text;article.append(folio,text);reader.append(article);}const nav=document.createElement('div'),prev=document.createElement('button'),next=document.createElement('button');prev.textContent='← Previous';next.textContent='Next →';prev.className=next.className='secondary';const turn=n=>reader.scrollBy({left:n*reader.clientWidth,behavior:'smooth'});prev.onclick=()=>turn(-1);next.onclick=()=>turn(1);reader.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();turn(e.key==='ArrowLeft'?-1:1);}};nav.append(prev,next);$('#story').append(reader,nav);$('#proof-section').hidden=!order.proof;if(order.proof){const proofUrl=await callProofUrl();$('#proof').src=proofUrl;$('#download-proof').href=proofUrl;$('#approve').disabled=order.status!=='proof_ready';$('#proof-confirm').disabled=order.status!=='proof_ready';$('#proof-note').textContent=order.customerApproved?'You approved this version. Our team must still release it before printing.':'Printing stays on hold until you approve this proof.';}$('#shipping').hidden=!order.shipments?.length;$('#tracking').replaceChildren();for(const s of order.shipments||[]){const p=document.createElement('p');p.textContent=[s.carrier?.name||s.carrier,s.trackingNumber].filter(Boolean).join(' · ');if(s.trackingUrl&&s.trackingUrl.startsWith('https://')){const a=document.createElement('a');a.href=s.trackingUrl;a.textContent=' Track delivery';a.target='_blank';a.rel='noopener';p.append(a);}$('#tracking').append(p);}}catch(e){$('#message').textContent=e.message;}}
async function callProofUrl(){return `/api/orders/${id}/file?proof=${encodeURIComponent(order.proof.hash)}`;}
$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(privateLink);$('#message').textContent='Private link copied.';}catch{$('#message').textContent='Copy the private link shown above.';}};
$('#refresh').onclick=refresh;
$('#pay').onclick=async()=>{try{$('#pay').disabled=true;const r=await call('checkout',{});location.assign(r.url);}catch(e){$('#message').textContent=e.message;$('#pay').disabled=false;await refresh();}};
$('#approve').onclick=async()=>{try{if(!$('#proof-confirm').checked)throw new Error('Check every page, then tick the approval box.');$('#approve').disabled=true;await call('approve-proof',{confirm:true,proofHash:order.proof.hash});await refresh();}catch(e){$('#message').textContent=e.message;$('#approve').disabled=false;}};
(async()=>{if(!/^[a-f0-9-]{36}$/.test(id||'')){$('#message').textContent='Open the private link from your saved book.';return;}if(key){try{await call('session',{token:key});}catch(e){$('#message').textContent=e.message;return;}}await refresh();})();
